"""Physical card, resource, equipment and zone movement mutations."""
from math import prod
from . import domain_soa_schema as schema


def emit_source(layout):
    specs=schema.array_specs(layout)
    text='''DFN int d_card_str_is(DX*c,int card,const char*key,const char*value){int id=d_card_template(c,card),k=-1;'''
    text+=''.join(f'if(d_streq(key,"{key}"))k={i};'for i,key in enumerate(schema.CARD_STR_FIELDS))
    text+='''if(k<0){d_fail(c,4);return 0;}if(card<=-2)return d_streq(d_card_default_str(id,k),value);int p=c->s->card_str_presence[card*KS+k];return p==2?d_eq(c,c->s->card_str_slot[card*KS+k],value):p==3?d_streq(d_card_default_str(id,k),value):!value;}
DFN int d_copy_card(DX*c,int side,int source,int owner){int id=d_card_template(c,source);if(d_bad(c)||!id)return -1;int card=d_make_card(c,side,d_card_name(id),-1);if(card<0)return -1;DS*f=c->s;f->card_bool_presence[card*KB+KB_copy]=2;f->card_bool_value[card*KB+KB_copy]=1;f->card_str_presence[card*KS+KS_original_character_id]=2;f->card_str_slot[card*KS+KS_original_character_id]=d_intern(c,d_card_default_str(id,KS_character_id));f->card_str_presence[card*KS+KS_character_id]=2;f->card_str_slot[card*KS+KS_character_id]=d_intern(c,"anhunqu");f->card_int_presence[card*KI+KI_expires_turn]=2;f->card_int_value[card*KI+KI_expires_turn]=d_pi(c,side,"turn_count")+1;return card;}
DFN void d_draw(DX*c,int side,int count,int type){if(!d_valid_side(c,side)||count<0||count>128||type< -1||type>2){d_fail(c,1);return;}for(int j=0;j<count&&!d_finished(c)&&!d_bad(c);j++){int n=c->s->zone_count[side*4+1],at=0;if(type>=0){at=-1;for(int k=0;k<n;k++){int card=c->s->zone_card_index[(side*4+1)*Z+k];if(d_card_str_is(c,card,"type",type==0?"tactic":type==1?"battle":"form")){at=k;break;}}if(at<0)break;}if(!n){int wins=d_pb(c,side,"empty_draw_wins");d_finish(c,wins?side:1-side,wins?"empty_draw_win":"empty_draw");break;}int card=c->s->zone_card_index[(side*4+1)*Z+at];d_remove_zone_card(c,side,1,card);if(c->s->zone_count[side*4]>=10)d_discard(c,side,card);else{d_zone_append(c,side,0,card);DX x=*c;x.side=side;x.actor=d_order_slot(c,side,0);x.card=-1;DEvt ev={};ev.card=card;d_fire(&x,"on_hand_added",&ev);}d_event(c);}}
DFN void d_draw_owned(DX*c,int owner,int reveal){int side=c->side,n=c->s->zone_count[side*4+1];for(int j=0;j<n;j++){int card=c->s->zone_card_index[(side*4+1)*Z+j];if(d_card_owner(c,card)==owner&&!d_card_bool(c,card,"copy")&&!d_card_bool(c,card,"derived")){d_remove_zone_card(c,side,1,card);d_add_hand(c,side,card,reveal);if(!reveal)d_event(c);return;}}}
DFN void d_shield(DX*c,DR r,int amount){if(d_finished(c)||d_bad(c)||(r.slot>=0&&!d_alive(c,r.side,r.slot)))return;int value=r.slot<0?d_pi(c,r.side,"shield"):d_ci(c,r.side,r.slot,"shield");if(amount>0){if((long long)value+amount>2147483647){d_fail(c,2);return;}value+=amount;}if(r.slot<0)d_set_pi(c,r.side,"shield",value);else d_set_ci(c,r.side,r.slot,"shield",value);d_event(c);}
DFN void d_heal(DX*c,DR r,int amount,DR source){if(d_finished(c)||d_bad(c))return;if(source.slot>=0&&d_alive(c,source.side,source.slot)){DX own=*c;own.side=source.side;own.actor=source.slot;own.card=-1;amount=d_decide(&own,"outgoing_heal",amount,nullptr,1);}int hp=r.slot<0?d_pi(c,r.side,"hp"):d_ci(c,r.side,r.slot,"hp");if(r.slot<0){if(d_pb(c,r.side,"life_locked"))return;}else{if(d_ci(c,r.side,r.slot,"down_turns"))return;if(hp<0)hp=0;}int actual=d_max_hp(c,r.side,r.slot)-hp;if(actual>amount)actual=amount;if(r.slot<0&&actual<=0)return;hp+=actual;if(r.slot<0)d_set_pi(c,r.side,"hp",hp);else d_set_ci(c,r.side,r.slot,"hp",hp);if(actual){d_event(c);DX own=*c;own.side=source.side>=0?source.side:r.side;own.actor=d_order_slot(c,own.side,0);own.card=-1;DEvt ev={};ev.target_side=r.side;ev.target=r.slot;ev.amount=actual;ev.attacker_side=source.side;ev.attacker=source.slot;d_fire(&own,"on_ally_healed",&ev);}}
DFN void d_import_stats(DX*c,int side,int actor){int h=side*C+actor;DS*f=c->s;int err=0,holder=d_holder(c,side,actor),id=d_template(c,side,actor);int base=f->character_base_attack_presence[h]==2?f->character_base_attack[h]:id?cattack[id]:d_ci(c,side,actor,"base_attack");int hp=f->character_base_max_hp_presence[h]==2?f->character_base_max_hp[h]:id?chp[id]:d_ci(c,side,actor,"base_max_hp");int growth=f->character_growth_attack_presence[h]==2?f->character_growth_attack[h]:0;int growth_hp=f->character_growth_max_hp_presence[h]==2?f->character_growth_max_hp[h]:0;if(f->character_int_presence[h*NC+CI_base_attack]>=2)growth=d_ci(c,side,actor,"base_attack")-base;if(f->character_int_presence[h*NC+CI_base_max_hp]>=2)growth_hp=d_ci(c,side,actor,"base_max_hp")-hp;f->character_base_attack_presence[h]=2;f->character_base_attack[h]=base;f->character_base_max_hp_presence[h]=2;f->character_base_max_hp[h]=hp;f->character_growth_attack_presence[h]=2;f->character_growth_attack[h]=growth;f->character_growth_max_hp_presence[h]=2;f->character_growth_max_hp[h]=growth_hp;f->character_int_presence[h*NC+CI_base_attack]=0;f->character_int_presence[h*NC+CI_base_max_hp]=0;}
DFN void d_grow(DX*c,int side,int actor,int attack,int hp){d_import_stats(c,side,actor);int h=side*C+actor;c->s->character_growth_attack[h]+=attack;c->s->character_growth_max_hp[h]+=hp;d_set_ci(c,side,actor,"max_hp",d_ci(c,side,actor,"max_hp")+hp);d_set_ci(c,side,actor,"hp",d_ci(c,side,actor,"hp")+hp);}
DFN void d_move_out(DX*c,int side,int actor,int reason){if(d_front(c,side)!=actor)return;DS*f=c->s;int h=side*C+actor;if(d_cb(c,side,actor,"summoned")){d_set_ci(c,side,actor,"hp",0);d_set_ci(c,side,actor,"shield",0);d_set_cb(c,side,actor,"disappeared",1);d_set_front(c,side,-1);f->player_last_front_presence[side]=1;f->player_last_front_slot[side]=0;int n=f->player_order_count[side];for(int i=0;i<n;i++)if(f->player_order_slot[side*C+i]==actor){for(int j=i;j<n-1;j++)f->player_order_slot[side*C+j]=f->player_order_slot[side*C+j+1];f->player_order_count[side]--;break;}d_event(c);return;}int last=d_alive(c,side,actor)&&!d_collapsed(c,side,actor)&&d_ci(c,side,actor,"harmony")>=d_harmony_cap(c);f->player_last_front_presence[side]=last?2:1;f->player_last_front_slot[side]=last?actor:0;DX x=*c;x.side=side;x.actor=actor;x.card=-1;if(reason==1&&d_alive(c,side,actor))d_fire(&x,"on_replaced",nullptr,1);d_set_front(c,side,-1);d_set_ci(c,side,actor,"shield",0);d_clear_effects(&x,"leave");d_fire(&x,"on_leave_front",nullptr,1,1);d_event(c);}
'''
    return text


def emit_equipment_source():
    return r'''
DFN void d_remove_effect_source(DX*c,int entity,int key){DS*f=c->s;for(int holder=0;holder<H;holder++)if(exists(f,holder)){for(int j=f->holder_effect_count[holder]-1;j>=0;j--){int e=holder*E+j;if(f->effect_source_entity_presence[e]==2&&f->effect_source_entity_slot[e]==entity&&f->effect_source_key_slot[e]==key&&d_effect_has_clear(c,e,"source_removed"))d_effect_remove(c,holder,j);}int side=holder_side(holder),actor=holder_char(holder);if(actor<0)f->player_effects_presence[side]=2;else f->character_effects_presence[side*C+actor]=2;}}
DFN void d_remove_weapon_ex(DX*c,int side,int actor,int restore){DS*f=c->s;int h=side*C+actor,sp=f->character_str_presence[h*NS+CS_shape];if(sp==2){int id=f->character_str_slot[h*NS+CS_shape],source=0;d_remove_effect_source(c,d_entity(c,DR{side,actor}),id);if(f->character_equipment_presence[h]==2)source=f->character_equipment_id_slot[h];else {int n=f->string_length[id],at=f->string_offset[id];char suffix[128];const char*prefix=":weapon:legacy:";int p=0;while(prefix[p]){suffix[p]=prefix[p];p++;}if(n+p>120){d_fail(c,2);return;}for(int j=0;j<n;j++)suffix[p+j]=f->string_bytes[at+j];suffix[p+n]=0;char name[160];name[0]='e';d_uint_text(name+1,d_entity(c,DR{side,actor}));int m=0;while(name[m])m++;for(int j=0;j<=p+n;j++)name[m+j]=suffix[j];source=d_intern(c,name);}d_remove_effect_source(c,d_entity(c,DR{side,actor}),source);}
 d_set_cstr(c,side,actor,"shape",nullptr);f->character_equipment_presence[h]=0;f->character_equipment_card[h]=0;f->character_equipment_id_slot[h]=0;f->character_equipment_source_slot[h]=0;
 if(restore){d_import_stats(c,side,actor);int hp=f->character_base_max_hp[h]+f->character_growth_max_hp[h];d_set_ci(c,side,actor,"max_hp",hp);if(d_ci(c,side,actor,"hp")>hp)d_set_ci(c,side,actor,"hp",hp);}}
DFN void d_remove_weapon(DX*c,int side,int actor){d_remove_weapon_ex(c,side,actor,1);}
DFN void d_set_shape(DX*c){int card=c->card,side=c->side,actor=c->actor;if(!d_card_str_is(c,card,"type","form")){d_fail(c,1);return;}d_import_stats(c,side,actor);d_remove_weapon_ex(c,side,actor,0);DS*f=c->s;int h=side*C+actor,serial=d_ci(c,side,actor,"equipment_seq");if(serial>=2147483647){d_fail(c,2);return;}serial++;d_set_ci(c,side,actor,"equipment_seq",serial);int id=d_card_template(c,card);d_set_cstr(c,side,actor,"shape",d_card_name(id));f->character_equipment_presence[h]=2;f->character_equipment_card[h]=id;f->character_equipment_id_slot[h]=d_identity_text(c,d_entity(c,DR{side,actor}),":weapon:",serial);f->character_equipment_source_slot[h]=card<=-2?0:f->card_entity_slot[card];int hp=d_card_int(c,card,"hp");if(hp){int grow=f->character_growth_max_hp[h];d_set_ci(c,side,actor,"max_hp",hp+(grow>0?grow:0));d_set_ci(c,side,actor,"hp",d_ci(c,side,actor,"max_hp"));}d_event(c);}
'''


def emit_random_helpers():
    return r'''
DFN void d_random_begin(DX*c,bmt_state_t*rng,int before){uint64_t seed=(uint64_t)c->s->rng[0];uint32_t words[2]={(uint32_t)seed,(uint32_t)(seed>>32)};bmt_seed_words(rng,words,words[1]?2:1);if(before){uint64_t value=0;bmt_getbits64(rng,63,&value);c->s->rng[0]=(long long)value;}}
DFN int d_random_index(DX*c,bmt_state_t*rng,int n){if(n<=0){d_fail(c,1);return 0;}int bits=bmt_bit_length_u64(n);uint64_t value=0;for(int j=0;j<4096;j++){bmt_getbits64(rng,bits,&value);if(value<(uint64_t)n)return (int)value;}d_fail(c,2);return 0;}
DFN void d_random_end(DX*c,bmt_state_t*rng){uint64_t value=0;bmt_getbits64(rng,63,&value);c->s->rng[0]=(long long)value;}
DFN int d_random_before(DX*c,int n){bmt_state_t rng;d_random_begin(c,&rng,1);return d_random_index(c,&rng,n);}
DFN void d_sample_before(DX*c,const int*items,int n,int count,int*out){if(n<0||n>C||count<0||count>n){d_fail(c,1);return;}bmt_state_t rng;d_random_begin(c,&rng,1);int pool[C];for(int j=0;j<n;j++)pool[j]=items[j];for(int j=0;j<count;j++){int pick=d_random_index(c,&rng,n-j);out[j]=pool[pick];pool[pick]=pool[n-j-1];}}
'''


def emit_context_mutations():
    return r'''
DFN void d_context_energy(DX*c,int side,int actor,int amount){int before=d_ci(c,side,actor,"energy");d_energy(c,side,actor,amount);if(d_ci(c,side,actor,"energy")!=before)d_event(c);}
DFN void d_context_grow(DX*c,int side,int actor,int attack,int hp){d_grow(c,side,actor,attack,hp);if(attack||hp)d_event(c);}
'''
